using System.Globalization;
using Microsoft.Windows.ApplicationModel.Resources;

namespace NetNewsWire.Windows;

/// <summary>
/// The app's strings, from Strings/&lt;language&gt;/Resources.resw (generated by Windows/Localization/generate.py
/// from strings.json), in the user's Windows display language. XAML uses x:Uid for the same resources.
/// A string a language lacks falls back to English, as does any string if the resources can't be loaded.
/// </summary>
internal static partial class Loc
{
    private static readonly ResourceLoader? loader = CreateLoader();

    public static string Get(string key)
    {
        try
        {
            if (loader?.GetString(key) is { Length: > 0 } value)
            {
                return value;
            }
        }
        catch (Exception e) when (e is System.Runtime.InteropServices.COMException or ArgumentException)
        {
            // Not in the resources: the English below.
        }
        return English.TryGetValue(key, out var english) ? english : key;
    }

    public static string Format(string key, params object?[] arguments) =>
        string.Format(CultureInfo.CurrentCulture, Get(key), arguments);

    private static ResourceLoader? CreateLoader()
    {
        try
        {
            return new ResourceLoader();
        }
        catch (Exception e) when (e is System.Runtime.InteropServices.COMException or FileNotFoundException)
        {
            System.Diagnostics.Debug.WriteLine($"String resources unavailable: {e.Message}");
            return null;
        }
    }
}
